1	package integration
2	
3	import (
4		"bytes"
5		"fmt"
6		"io"
7		"net"
8		"net/http"
9		"os"
10		"os/exec"
11		"path/filepath"
12		"strings"
13		"sync"
14		"testing"
15		"time"
16	)
17	
18	// This file verifies online configuration switches through the admin API
19	// (POST /load) against a real `caddy` subprocess:
20	//
21	//   - a successful load starts serving the new configuration as soon as the
22	//     admin response reports success, while requests that were already in
23	//     flight keep being served by the configuration that accepted them;
24	//   - a configuration that fails to parse/provision/start is rejected and the
25	//     previously running configuration keeps serving without any gap in which
26	//     the listen address is unconfigured;
27	//   - success, failure and success again stay isolated: each round's requests
28	//     and responses match exactly the configuration of that round.
29	//
30	// The matrix runs twice: on a plaintext HTTP/1.1 listener (native JSON
31	// submitted to /load) and on an HTTPS listener configured with the Caddyfile
32	// `tls internal` (Caddyfile submitted to /load, negotiated over HTTP/2). The
33	// protocol must not change any switch boundary, rollback or in-flight
34	// semantics.
35	
36	const (
37		// holdPrefix/holdSuffix are the two halves of the response body that the
38		// test upstream sends for /hold. The prefix is flushed before the config
39		// switch; the suffix is only flushed when the test releases the upstream
40		// connection, so the client can prove the in-flight response is neither
41		// spliced with the new configuration, truncated nor duplicated.
42		holdPrefix = "A-inflight-prefix----"
43		holdSuffix = "A-inflight-suffix----"
44	
45		versionABody = "variant-a-payload"
46		versionBBody = "variant-b-payload"
47	)
48	
49	// reloadHoldUpstream is a test-process HTTP/1.1 upstream that /hold is proxied
50	// to. For each /hold request it writes the A status line, an A marker header
51	// and the A body prefix, then parks the (hijacked) connection until the test
52	// releases it, at which point it writes the suffix and the terminating chunk
53	// and closes the connection.
54	type reloadHoldUpstream struct {
55		ln          net.Listener
56		mu          sync.Mutex
57		held        []net.Conn
58		variantHits map[string]int
59	}
60	
61	func newReloadHoldUpstream(t *testing.T) *reloadHoldUpstream {
62		t.Helper()
63		ln, err := net.Listen("tcp", "127.0.0.1:0")
64		if err != nil {
65			t.Fatalf("listen for hold upstream: %v", err)
66		}
67		u := &reloadHoldUpstream{
68			ln:          ln,
69			variantHits: make(map[string]int),
70		}
71		srv := &http.Server{Handler: http.HandlerFunc(u.handle)}
72		go srv.Serve(ln)
73		t.Cleanup(func() { srv.Close(); ln.Close() })
74		return u
75	}
76	
77	func (u *reloadHoldUpstream) addr() string { return u.ln.Addr().String() }
78	
79	func (u *reloadHoldUpstream) variantHit(variant string) int {
80		u.mu.Lock()
81		defer u.mu.Unlock()
82		return u.variantHits[variant]
83	}
84	
85	// releaseAll finalizes every held response with the A suffix and then closes
86	// its connection. It is the only way a held response may complete.
87	func (u *reloadHoldUpstream) releaseAll() {
88		u.mu.Lock()
89		conns := u.held
90		u.held = nil
91		u.mu.Unlock()
92		for _, conn := range conns {
93			fmt.Fprintf(conn, "%x\r\n%s\r\n", len(holdSuffix), holdSuffix)
94			_, _ = io.WriteString(conn, "0\r\n\r\n")
95			_ = conn.Close()
96		}
97	}
98	
99	func (u *reloadHoldUpstream) handle(w http.ResponseWriter, r *http.Request) {
100		variant := r.Header.Get("X-Variant")
101		u.mu.Lock()
102		u.variantHits[variant]++
103		u.mu.Unlock()
104	
105		conn, rw, err := w.(http.Hijacker).Hijack()
106		if err != nil {
107			panic(err)
108		}
109		_, _ = io.WriteString(rw,
110			"HTTP/1.1 200 OK\r\n"+
111				"X-Hold-Marker: hold-A\r\n"+
112				"Transfer-Encoding: chunked\r\n"+
113				"\r\n")
114		fmt.Fprintf(rw, "%x\r\n%s\r\n", len(holdPrefix), holdPrefix)
115		_ = rw.Flush()
116	
117		u.mu.Lock()
118		u.held = append(u.held, conn)
119		u.mu.Unlock()
120	
121		// park the handler until Caddy (or releaseAll) closes the connection;
122		// after a Hijack the stdlib server no longer touches this connection
123		_, _ = io.Copy(io.Discard, rw)
124	}
125	
126	// inflightHold is one /hold request running in its own goroutine while the
127	// test drives configuration switches on other connections.
128	type inflightHold struct {
129		prefixReady chan struct{}
130		done        chan struct{}
131	
132		resp      *http.Response
133		prefix    []byte
134		prefixErr error
135		rest      []byte
136		restErr   error
137	}
138	
139	func startInflightHold(t *testing.T, client *http.Client, baseURL string) *inflightHold {
140		t.Helper()
141		h := &inflightHold{
142			prefixReady: make(chan struct{}),
143			done:        make(chan struct{}),
144		}
145		go func() {
146			defer close(h.done)
147			resp, err := client.Get(baseURL + "/hold")
148			if err != nil {
149				h.prefixErr = err
150				close(h.prefixReady)
151				return
152			}
153			h.resp = resp
154			h.prefix = make([]byte, len(holdPrefix))
155			_, h.prefixErr = io.ReadFull(resp.Body, h.prefix)
156			close(h.prefixReady)
157			if h.prefixErr != nil {
158				return
159			}
160			h.rest, h.restErr = io.ReadAll(resp.Body)
161		}()
162		return h
163	}
164	
165	// waitPrefix waits until the A status line, marker header and prefix body have
166	// arrived; the configuration switch must only be started after this.
167	func (h *inflightHold) waitPrefix(t *testing.T) {
168		t.Helper()
169		select {
170		case <-h.prefixReady:
171		case <-time.After(30 * time.Second):
172			t.Fatal("held request never produced its A prefix")
173		}
174		if h.prefixErr != nil {
175			t.Fatalf("reading held prefix: %v", h.prefixErr)
176		}
177		if string(h.prefix) != holdPrefix {
178			t.Fatalf("held prefix: got %q, want %q", h.prefix, holdPrefix)
179		}
180		if h.resp.StatusCode != http.StatusOK {
181			t.Fatalf("held status: got %d, want 200", h.resp.StatusCode)
182		}
183		if got := h.resp.Header.Get("X-Hold-Marker"); got != "hold-A" {
184			t.Fatalf("held marker: got %q, want hold-A", got)
185		}
186	}
187	
188	// assertStillOpen proves the in-flight response has not picked up any further
189	// data (in particular no B content) and has not ended while another
190	// configuration is active.
191	func (h *inflightHold) assertStillOpen(t *testing.T, phase string) {
192		t.Helper()
193		select {
194		case <-h.done:
195			t.Fatalf("held request completed during %s before the upstream was released", phase)
196		case <-time.After(500 * time.Millisecond):
197		}
198	}
199	
200	// waitAndAssertComplete waits for the held response to end (after the upstream
201	// release) and asserts it is exactly the A response in full: A status and
202	// marker already asserted at prefix time, plus a clean read of exactly the A
203	// suffix, with no B payload spliced in, no truncation and no duplicated
204	// prefix.
205	func (h *inflightHold) waitAndAssertComplete(t *testing.T, wantProto int) {
206		t.Helper()
207		select {
208		case <-h.done:
209		case <-time.After(10 * time.Second):
210			t.Fatal("held request never completed after the upstream was released")
211		}
212		if h.restErr != nil {
213			t.Fatalf("reading held response to completion: %v", h.restErr)
214		}
215		if string(h.rest) != holdSuffix {
216			t.Errorf("held suffix: got %q, want %q", h.rest, holdSuffix)
217		}
218		full := string(append(append([]byte{}, h.prefix...), h.rest...))
219		if want := holdPrefix + holdSuffix; full != want {
220			t.Errorf("held full body: got %q, want %q", full, want)
221		}
222		if bytes.Count([]byte(full), []byte(holdPrefix)) != 1 {
223			t.Errorf("held prefix was delivered more than once: %q", full)
224		}
225		if strings.Contains(full, versionBBody) {
226			t.Errorf("held response was spliced with B content: %q", full)
227		}
228		if h.resp.ProtoMajor != wantProto {
229			t.Errorf("held response protocol: got HTTP/%d, want HTTP/%d", h.resp.ProtoMajor, wantProto)
230		}
231	}
232	
233	// versionResult is the exact /version answer a configuration gave one client.
234	type versionResult struct {
235		status  int
236		variant string
237		body    string
238		proto   int
239	}
240	
241	// versionExpectation is the exact /version answer one configuration must give.
242	type versionExpectation struct {
243		status  int
244		variant string
245		body    string
246	}
247	
248	var (
249		versionA = versionExpectation{status: http.StatusCreated, variant: "A", body: versionABody}
250		versionB = versionExpectation{status: http.StatusAccepted, variant: "B", body: versionBBody}
251	)
252	
253	func fetchVersion(t *testing.T, client *http.Client, baseURL string) versionResult {
254		t.Helper()
255		resp, err := client.Get(baseURL + "/version")
256		if err != nil {
257			t.Fatalf("GET /version: %v", err)
258		}
259		defer resp.Body.Close()
260		body, err := io.ReadAll(resp.Body)
261		if err != nil {
262			t.Fatalf("reading /version body: %v", err)
263		}
264		return versionResult{
265			status:  resp.StatusCode,
266			variant: resp.Header.Get("X-Variant"),
267			body:    string(body),
268			proto:   resp.ProtoMajor,
269		}
270	}
271	
272	func (v versionResult) assertMatches(t *testing.T, want versionExpectation, wantProto int, where string) {
273		t.Helper()
274		if v.status != want.status {
275			t.Errorf("%s: /version status: got %d, want %d", where, v.status, want.status)
276		}
277		if v.variant != want.variant {
278			t.Errorf("%s: /version X-Variant: got %q, want %q", where, v.variant, want.variant)
279		}
280		if v.body != want.body {
281			t.Errorf("%s: /version body: got %q, want %q", where, v.body, want.body)
282		}
283		if v.proto != wantProto {
284			t.Errorf("%s: /version protocol: got HTTP/%d, want HTTP/%d", where, v.proto, wantProto)
285		}
286	}
287	
288	// assertOnlyVariant issues /version over both the shared keep-alive client and
289	// brand-new connections, so an old listener still accepting new connections
290	// after a switch (which would answer the previous variant) cannot hide, and
291	// neither can a brief window in which the address answers nothing.
292	func assertOnlyVariant(t *testing.T, baseURL string, h2 bool, wantProto int, want versionExpectation, where string) {
293		t.Helper()
294		shared := newFailoverClient(h2)
295		for i := 0; i < 16; i++ {
296			client := shared
297			if i%2 == 0 {
298				client = newFailoverClient(h2) // force a brand-new connection
299			}
300			got := fetchVersion(t, client, baseURL)
301			got.assertMatches(t, want, wantProto, fmt.Sprintf("%s request %d", where, i))
302		}
303	}
304	
305	// switchProbe continuously issues /version requests on its own keep-alive
306	// connections while a configuration switch is in flight. Every answer must be
307	// a well-formed A or B answer (which side of the switch boundary a request
308	// lands on is unspecified); a connection error, a missing listener or any
309	// third answer shape would mean the address was briefly unconfigured.
310	type switchProbe struct {
311		done           chan struct{}
312		wg             sync.WaitGroup
313		mu             sync.Mutex
314		errs           []string
315		odd            []string
316		aCount, bCount int
317	}
318	
319	func startSwitchProbe(t *testing.T, baseURL string, h2 bool) *switchProbe {
320		t.Helper()
321		p := &switchProbe{done: make(chan struct{})}
322		wantProto := 1
323		if h2 {
324			wantProto = 2
325		}
326		for w := 0; w < 4; w++ {
327			p.wg.Add(1)
328			go func() {
329				defer p.wg.Done()
330				// one client per worker: connections are reused, so probing never
331				// exhausts the ephemeral port range
332				client := newFailoverClient(h2)
333				for {
334					select {
335					case <-p.done:
336						return
337					default:
338					}
339					resp, err := client.Get(baseURL + "/version")
340					if err != nil {
341						p.mu.Lock()
342						p.errs = append(p.errs, err.Error())
343						p.mu.Unlock()
344						continue
345					}
346					body, _ := io.ReadAll(resp.Body)
347					resp.Body.Close()
348					got := versionResult{
349						status:  resp.StatusCode,
350						variant: resp.Header.Get("X-Variant"),
351						body:    string(body),
352						proto:   resp.ProtoMajor,
353					}
354					p.mu.Lock()
355					switch {
356					case got.status == versionA.status && got.variant == "A" && got.body == versionABody && got.proto == wantProto:
357						p.aCount++
358					case got.status == versionB.status && got.variant == "B" && got.body == versionBBody && got.proto == wantProto:
359						p.bCount++
360					default:
361						p.odd = append(p.odd, fmt.Sprintf("%d %q %q HTTP/%d", got.status, got.variant, got.body, got.proto))
362					}
363					p.mu.Unlock()
364				}
365			}()
366		}
367		return p
368	}
369	
370	func (p *switchProbe) stop() { close(p.done); p.wg.Wait() }
371	
372	// assertCleanAcrossSwitch checks that probing saw neither errors nor malformed
373	// answers, and that it observed both sides of the boundary (A before the switch
374	// completed, B afterwards).
375	func (p *switchProbe) assertCleanAcrossSwitch(t *testing.T, where string) {
376		t.Helper()
377		p.mu.Lock()
378		defer p.mu.Unlock()
379		for _, e := range p.errs {
380			t.Errorf("%s: request failed while the switch was in flight: %s", where, e)
381		}
382		for _, o := range p.odd {
383			t.Errorf("%s: neither A nor B answer while the switch was in flight: %s", where, o)
384		}
385		if p.aCount == 0 {
386			t.Errorf("%s: probe never observed an A answer before the switch completed", where)
387		}
388		if p.bCount == 0 {
389			t.Errorf("%s: probe never observed a B answer after the switch completed", where)
390		}
391	}
392	
393	// postLoad submits a complete configuration to POST /load.
394	func postLoad(t *testing.T, adminURL, contentType string, body io.Reader) (int, string) {
395		t.Helper()
396		client := &http.Client{Timeout: 30 * time.Second}
397		resp, err := client.Post(adminURL+"/load", contentType, body)
398		if err != nil {
399			t.Fatalf("POST /load: %v", err)
400		}
401		defer resp.Body.Close()
402		respBody, _ := io.ReadAll(resp.Body)
403		return resp.StatusCode, string(respBody)
404	}
405	
406	// assertLoadSucceeds submits a configuration and requires the admin API to
407	// accept it. By the time the 200 is returned the new configuration must be the
408	// one answering new requests.
409	func assertLoadSucceeds(t *testing.T, adminURL, contentType, body, label string) {
410		t.Helper()
411		status, respBody := postLoad(t, adminURL, contentType, strings.NewReader(body))
412		if status != http.StatusOK {
413			t.Fatalf("%s: POST /load status: got %d, want 200; body: %s", label, status, respBody)
414		}
415		if respBody != "" {
416			t.Errorf("%s: POST /load body: got %q, want empty", label, respBody)
417		}
418	}
419	
420	// assertLoadRejected submits an invalid configuration and requires it to be
421	// refused with the duplicate-listener validation error; nothing about the
422	// running configuration may change.
423	func assertLoadRejected(t *testing.T, adminURL, badBody, label string) {
424		t.Helper()
425		status, respBody := postLoad(t, adminURL, "application/json", strings.NewReader(badBody))
426		if status != http.StatusBadRequest {
427			t.Fatalf("%s: POST /load status: got %d, want 400; body: %s", label, status, respBody)
428		}
429		if !strings.Contains(respBody, "listener address repeated") {
430			t.Fatalf("%s: POST /load error: got %q, want it to mention a repeated listener address", label, respBody)
431		}
432	}
433	
434	// startReloadCaddy launches `caddy run` with the given initial configuration
435	// and waits until /version answers wantReadyStatus, proving the instance owns
436	// the listen address.
437	func startReloadCaddy(t *testing.T, bin, cfgPath, adapter, runDir, adminURL, baseURL string, h2 bool, wantReadyStatus int) *caddyInstance {
438		t.Helper()
439	
440		logFile, err := os.Create(filepath.Join(runDir, "caddy.log"))
441		if err != nil {
442			t.Fatalf("creating log file: %v", err)
443		}
444		args := []string{"run", "--config", cfgPath}
445		if adapter != "" {
446			args = append(args, "--adapter", adapter)
447		}
448		cmd := exec.Command(bin, args...)
449		cmd.Stdout = logFile
450		cmd.Stderr = logFile
451		// isolate every on-disk artifact (autosave, internal CA, locks) from the
452		// developer machine and from other test runs
453		cmd.Env = isolatedCaddyEnv(runDir, "state")
454		if err := cmd.Start(); err != nil {
455			logFile.Close()
456			t.Fatalf("starting caddy: %v", err)
457		}
458	
459		inst := &caddyInstance{
460			cmd:      cmd,
461			logPath:  logFile.Name(),
462			waitDone: make(chan error, 1),
463			adminURL: adminURL,
464		}
465		go func() { inst.waitDone <- cmd.Wait(); logFile.Close() }()
466	
467		client := newFailoverClient(h2)
468		deadline := time.Now().Add(60 * time.Second)
469		for time.Now().Before(deadline) {
470			select {
471			case err := <-inst.waitDone:
472				t.Fatalf("caddy exited before becoming ready: %v\n%s", err, inst.tailLog())
473			default:
474			}
475			resp, err := client.Get(baseURL + "/version")
476			if err == nil {
477				_, _ = io.Copy(io.Discard, resp.Body)
478				resp.Body.Close()
479				if resp.StatusCode == wantReadyStatus {
480					return inst
481				}
482			}
483			time.Sleep(50 * time.Millisecond)
484		}
485		t.Fatalf("caddy did not become ready within 60s\n%s", inst.tailLog())
486		return nil
487	}
488	
489	// config builders for the plaintext HTTP/1.1 matrix (native JSON over /load).
490	
491	func reloadJSONA(adminAddr, siteAddr, upstreamAddr string) string {
492		return fmt.Sprintf(`{
493		"admin": {"listen": %q},
494		"apps": {
495			"http": {
496				"grace_period": "60s",
497				"servers": {
498					"srv0": {
499						"listen": [%q],
500						"routes": [
501							{
502								"match": [{"path": ["/version"]}],
503								"handle": [{
504									"handler": "static_response",
505									"status_code": 201,
506									"headers": {"X-Variant": ["A"]},
507									"body": %q
508								}]
509							},
510							{
511								"match": [{"path": ["/hold"]}],
512								"handle": [{
513									"handler": "reverse_proxy",
514									"headers": {"request": {"set": {"X-Variant": ["A"]}}},
515									"upstreams": [{"dial": %q}]
516								}]
517							}
518						]
519					}
520				}
521			}
522		}
523	}`, adminAddr, siteAddr, versionABody, upstreamAddr)
524	}
525	
526	func reloadJSONB(adminAddr, siteAddr string) string {
527		return fmt.Sprintf(`{
528		"admin": {"listen": %q},
529		"apps": {
530			"http": {
531				"grace_period": "60s",
532				"servers": {
533					"srv0": {
534						"listen": [%q],
535						"routes": [
536							{
537								"match": [{"path": ["/version"]}],
538								"handle": [{
539									"handler": "static_response",
540									"status_code": 202,
541									"headers": {"X-Variant": ["B"]},
542									"body": %q
543								}]
544							}
545						]
546					}
547				}
548			}
549		}
550	}`, adminAddr, siteAddr, versionBBody)
551	}
552	
553	// reloadJSONBad is deliberately invalid: two HTTP servers declare the same
554	// listen address, which Validate() must reject before anything starts.
555	func reloadJSONBad(adminAddr, siteAddr string) string {
556		return fmt.Sprintf(`{
557		"admin": {"listen": %q},
558		"apps": {
559			"http": {
560				"grace_period": "60s",
561				"servers": {
562					"one": {"listen": [%q], "routes": []},
563					"two": {"listen": [%q], "routes": []}
564				}
565			}
566		}
567	}`, adminAddr, siteAddr, siteAddr)
568	}
569	
570	// config builders for the HTTPS HTTP/2 matrix (Caddyfile with `tls internal`
571	// submitted to /load).
572	
573	func reloadCaddyfileA(adminAddr, siteAddr, upstreamAddr string) string {
574		return fmt.Sprintf(`{
575		skip_install_trust
576		admin %s
577		grace_period 60s
578	}
579	%s {
580		tls internal
581		handle /version {
582			header X-Variant A
583			respond %q 201
584		}
585		handle /hold {
586			reverse_proxy %s {
587				header_up X-Variant A
588			}
589		}
590	}
591	`, adminAddr, siteAddr, versionABody, upstreamAddr)
592	}
593	
594	func reloadCaddyfileB(adminAddr, siteAddr string) string {
595		return fmt.Sprintf(`{
596		skip_install_trust
597		admin %s
598		grace_period 60s
599	}
600	%s {
601		tls internal
602		handle /version {
603			header X-Variant B
604			respond %q 202
605		}
606	}
607	`, adminAddr, siteAddr, versionBBody)
608	}
609	
610	// reloadCase parameterizes one protocol matrix.
611	type reloadCase struct {
612		name        string
613		h2          bool
614		wantProto   int
615		siteAddr    string
616		adminAddr   string
617		contentType string // Content-Type used when submitting A and B to /load
618	}
619	
620	// TestConfigReloadInFlightIsolation drives the complete online-switch matrix
621	// on a real caddy binary for a plaintext HTTP/1.1 listener and an HTTPS
622	// HTTP/2 listener:
623	//
624	//  1. A is started and serves A on /version.
625	//  2. a /hold request is opened; once its A prefix has arrived, B is loaded;
626	//  3. from the moment /load answers 200, only B answers new /version requests
627	//     while the held A response stays exactly where it was; concurrent probes
628	//     during the commit prove the address is continuously available;
629	//  4. releasing the upstream completes the held response as exactly A;
630	//  5. an invalid duplicate-listener config is rejected and B keeps serving;
631	//  6. A loads again and a second /hold is opened, interleaving the three
632	//     events: a rolled-back failure (A keeps serving, hold unchanged), then a
633	//     successful commit while the same hold is open (B serves new requests,
634	//     address continuously available), and only then is the request released
635	//     to finish as exactly A;
636	//  7. one more successful load closes the success/failure/success sequence.
637	func TestConfigReloadInFlightIsolation(t *testing.T) {
638		bin := buildCaddyBinary(t)
639	
640		for _, tc := range []reloadCase{
641			{
642				name:        "HTTP/1.1 plaintext",
643				h2:          false,
644				wantProto:   1,
645				siteAddr:    "127.0.0.1:9088",
646				adminAddr:   "127.0.0.1:2992",
647				contentType: "application/json",
648			},
649			{
650				name:        "HTTP/2 over TLS internal",
651				h2:          true,
652				wantProto:   2,
653				siteAddr:    "localhost:9451",
654				adminAddr:   "127.0.0.1:2991",
655				contentType: "text/caddyfile",
656			},
657		} {
658			t.Run(tc.name, func(t *testing.T) {
659				runReloadMatrix(t, bin, tc)
660			})
661		}
662	}
663	
664	func runReloadMatrix(t *testing.T, bin string, tc reloadCase) {
665		upstream := newReloadHoldUpstream(t)
666	
667		adminURL := "http://" + tc.adminAddr
668		scheme := "http"
669		if tc.h2 {
670			scheme = "https"
671		}
672		baseURL := scheme + "://" + tc.siteAddr
673	
674		var cfgA, cfgB, initialCfg, initialName, adapter string
675		if tc.h2 {
676			initialName = "initial.Caddyfile"
677			adapter = "caddyfile"
678			cfgA = reloadCaddyfileA(tc.adminAddr, tc.siteAddr, upstream.addr())
679			cfgB = reloadCaddyfileB(tc.adminAddr, tc.siteAddr)
680		} else {
681			initialName = "initial.json"
682			cfgA = reloadJSONA(tc.adminAddr, tc.siteAddr, upstream.addr())
683			cfgB = reloadJSONB(tc.adminAddr, tc.siteAddr)
684		}
685		initialCfg = cfgA
686		cfgBad := reloadJSONBad(tc.adminAddr, tc.siteAddr)
687	
688		runDir := t.TempDir()
689		cfgPath := filepath.Join(runDir, initialName)
690		if err := os.WriteFile(cfgPath, []byte(initialCfg), 0o600); err != nil {
691			t.Fatalf("writing initial config: %v", err)
692		}
693	
694		inst := startReloadCaddy(t, bin, cfgPath, adapter, runDir, adminURL, baseURL, tc.h2, versionA.status)
695		t.Cleanup(func() { inst.stopCaddy(t) })
696	
697		// the held stream must outlive ordinary request deadlines, the rest of
698		// the matrix uses the standard bounded client
699		holdClient := newFailoverClient(tc.h2)
700		holdClient.Timeout = 0
701		client := newFailoverClient(tc.h2)
702	
703		// 1. A is the running configuration.
704		fetchVersion(t, client, baseURL).assertMatches(t, versionA, tc.wantProto, "initial A")
705	
706		// 2. open /hold and wait for the A prefix before switching anything.
707		held := startInflightHold(t, holdClient, baseURL)
708		held.waitPrefix(t)
709		if got := upstream.variantHit("A"); got != 1 {
710			t.Fatalf("upstream X-Variant=A hits: got %d, want 1", got)
711		}
712		if got := upstream.variantHit("B"); got != 0 {
713			t.Fatalf("upstream unexpectedly received X-Variant=B %d times", got)
714		}
715	
716		// everything immediately before the switch is still A
717		fetchVersion(t, client, baseURL).assertMatches(t, versionA, tc.wantProto, "pre-switch")
718	
719		// 3. load B while the address is being hammered; once this returns, new
720		// requests only ever see B and the address never stopped answering.
721		probe := startSwitchProbe(t, baseURL, tc.h2)
722		// let the probe demonstrably observe A before submitting B
723		time.Sleep(100 * time.Millisecond)
724		assertLoadSucceeds(t, adminURL, tc.contentType, cfgB, "load B")
725		// the successful response already marks the boundary; let probes observe
726		// the B side as well before stopping them
727		time.Sleep(100 * time.Millisecond)
728		probe.stop()
729		probe.assertCleanAcrossSwitch(t, "load B")
730		assertOnlyVariant(t, baseURL, tc.h2, tc.wantProto, versionB, "after B load")
731	
732		// the held response must still be exactly the open A response: no
733		// completion and no extra (B) bytes while B serves new requests
734		held.assertStillOpen(t, "B active")
735	
736		// 4. releasing the upstream finalizes the old response as exactly A.
737		upstream.releaseAll()
738		held.waitAndAssertComplete(t, tc.wantProto)
739		if got := upstream.variantHit("A"); got != 1 {
740			t.Errorf("upstream X-Variant=A hits after release: got %d, want still 1", got)
741		}
742	
743		// 5. a rejected load must not change anything: B keeps serving.
744		assertLoadRejected(t, adminURL, cfgBad, "bad config while B active")
745		assertOnlyVariant(t, baseURL, tc.h2, tc.wantProto, versionB, "after rejected load on B")
746	
747		// 6. A loads successfully again; then a second /hold request is opened and
748		// kept open while the other two events interleave around it: first a
749		// rejected (rolled back) load, then a successful commit. This fixes the
750		// ordering of commit completion, rollback and request release.
751		assertLoadSucceeds(t, adminURL, tc.contentType, cfgA, "reload A")
752		assertOnlyVariant(t, baseURL, tc.h2, tc.wantProto, versionA, "after A reload")
753	
754		held2 := startInflightHold(t, holdClient, baseURL)
755		held2.waitPrefix(t)
756		if got := upstream.variantHit("A"); got != 2 {
757			t.Fatalf("upstream X-Variant=A hits after second hold: got %d, want 2", got)
758		}
759	
760		// 6b. rollback while the request is held: rejected, A keeps serving, and
761		// the held response neither completes nor changes.
762		assertLoadRejected(t, adminURL, cfgBad, "bad config while A active")
763		assertOnlyVariant(t, baseURL, tc.h2, tc.wantProto, versionA, "after rejected load on A")
764		held2.assertStillOpen(t, "rollback while held")
765	
766		// 6c. successful commit while the very same request is held: from the
767		// successful response onwards only B answers new requests, and the address
768		// is continuously available across the boundary.
769		probe2 := startSwitchProbe(t, baseURL, tc.h2)
770		time.Sleep(100 * time.Millisecond)
771		assertLoadSucceeds(t, adminURL, tc.contentType, cfgB, "reload B while held")
772		time.Sleep(100 * time.Millisecond)
773		probe2.stop()
774		probe2.assertCleanAcrossSwitch(t, "reload B while held")
775		assertOnlyVariant(t, baseURL, tc.h2, tc.wantProto, versionB, "after commit while held")
776		held2.assertStillOpen(t, "successful commit while held")
777	
778		// 6d. only now is the request released; it was accepted by A, survived
779		// both a rolled-back failure and a successful commit, and must finish as
780		// exactly A with no B content, truncation or duplication.
781		upstream.releaseAll()
782		held2.waitAndAssertComplete(t, tc.wantProto)
783		if got := upstream.variantHit("A"); got != 2 {
784			t.Errorf("upstream X-Variant=A hits after second release: got %d, want still 2", got)
785		}
786	
787		// 7. one last successful load (A again) completes the
788		// success/failure/success/failure/success chain; every round must stay
789		// isolated from the others.
790		assertLoadSucceeds(t, adminURL, tc.contentType, cfgA, "final reload A")
791		assertOnlyVariant(t, baseURL, tc.h2, tc.wantProto, versionA, "after final A load")
792	}
