408	// JoinNetworkAddress combines network, host, and port into a single
409	// address string of the form accepted by ParseNetworkAddress(). For
410	// unix sockets, the network should be "unix" (or "unixgram" or
411	// "unixpacket") and the path to the socket should be given as the
412	// host parameter.
413	func JoinNetworkAddress(network, host, port string) string {
414		var a string
415		if network != "" {
416			a = network + "/"
417		}
418		if (host != "" && port == "") || IsUnixNetwork(network) || IsFdNetwork(network) {
419			a += host
